create function pg_temp.guidance_save(note text) returns jsonb language sql as $$select public.product_command('development.safety.save',jsonb_build_object('child_id','d3000000-0000-4000-8000-000000000002','instructions',note),gen_random_uuid())$$;
grant execute on function pg_temp.guidance_save(text) to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_safety_children),2,'Guardian projection includes own children before any instruction exists');
select lives_ok($$select pg_temp.guidance_save('Synthetic instruction: use the marked warm-up area.')$$,'Current guardian saves concise current training instructions');
select is((select instructions from public.development_safety_instructions where child_id='d3000000-0000-4000-8000-000000000002'),'Synthetic instruction: use the marked warm-up area.','Guardian reads own current instructions');
select is((select updated_by from public.development_safety_instructions where child_id='d3000000-0000-4000-8000-000000000002'),'d1000000-0000-4000-8000-000000000001'::uuid,'Instruction actor comes from the authenticated user');
select throws_ok($$select pg_temp.guidance_save(repeat('x',1001))$$,'22023',null,'SQL rejects instructions longer than the bounded field');
select throws_ok($$update public.development_safety_instructions set instructions='Bypass command'$$,'42501',null,'Direct safety mutations are denied');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_safety_instructions),0,'Unrelated family cannot inspect safety instructions');
select throws_ok($$select pg_temp.guidance_save('Unrelated parent write')$$,'42501',null,'Unrelated parent cannot alter safety instructions');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_safety_children where instructions<>''),1,'Current assigned coach can read a rostered child instruction');
select is((select count(*)::int from public.development_safety_instructions),0,'Coach cannot read raw safety metadata containing the guardian author identifier');
select is((select count(*)::int from public.development_safety_children),1,'Coach safety projection excludes an unassigned sibling');
select is((select can_edit from public.development_safety_children),false,'Coach projection is explicitly read-only');
select ok(not exists(select 1 from public.development_safety_children k where to_jsonb(k) ? 'family_id'),'Coach projection does not expose family or guardian identifiers');
select throws_ok($$select pg_temp.guidance_save('Coach cannot overwrite guardian instruction')$$,'42501',null,'Coach cannot edit instructions');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000007","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_safety_children),0,'Same-branch unassigned coach cannot read instructions');
reset role;
insert into public.coach_substitutions(session_id,coach_id,starts_at,ends_at,reason) values('d2000000-0000-4000-8000-000000000007','d1000000-0000-4000-8000-000000000007',now()-interval '1 hour',now()+interval '1 hour','Synthetic temporary assignment');
set local role authenticated;
select is((select count(*)::int from public.development_safety_children where instructions<>''),1,'Active substitute sees only relevant roster instruction');
reset role;
update public.coach_substitutions set revoked_at=now() where coach_id='d1000000-0000-4000-8000-000000000007';
set local role authenticated;
select is((select count(*)::int from public.development_safety_children),0,'Revoked substitute loses current instruction access');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_safety_instructions),0,'Branch role without a safety grant cannot read instructions');
select throws_ok($$select pg_temp.guidance_save('Branch without capability')$$,'42501',null,'Branch without a safety grant cannot edit instructions');
reset role;
insert into public.product_permissions(user_id,permission,branch_id) values('d1000000-0000-4000-8000-000000000005','development.safety','d2000000-0000-4000-8000-000000000001'),('d1000000-0000-4000-8000-000000000006','development.safety','d2000000-0000-4000-8000-000000000001');
set local role authenticated;
select is((select count(*)::int from public.development_safety_instructions),1,'Explicitly authorized family branch reads instructions');
select lives_ok($$select pg_temp.guidance_save('Synthetic instruction: confirm the marked practice area.')$$,'Explicitly authorized branch updates concise instructions');
reset role;
delete from public.family_branches where family_id='d3000000-0000-4000-8000-000000000001';
