select is((select count(*)::int from public.development_safety_instructions),0,'Sales cannot read instructions even with a forged safety grant');
select throws_ok($$select pg_temp.guidance_save('Sales cannot update instructions')$$,'42501',null,'Sales cannot edit instructions even with a grant');
