insert into public.product_permissions(user_id,permission) values('d1000000-0000-4000-8000-000000000008','development.safety');
set local role authenticated;
select is((select count(*)::int from public.development_safety_instructions),1,'Head Office with a global safety grant reads instructions');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_safety_instructions),0,'Owner requires AAL2 for safety data');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select is((select count(*)::int from public.development_safety_instructions),1,'Verified Owner can inspect current instructions');
reset role;
update public.academy_classes set active=false where id='d2000000-0000-4000-8000-000000000006';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_safety_children),0,'Inactive class does not authorize coach safety access');
