set local role authenticated;
select is((select count(*)::int from public.development_safety_children),0,'Historical sessions do not authorize current safety instruction access');
reset role;
update public.class_sessions set starts_at=now()-interval '2 hours',ends_at=now()-interval '1 hour' where id='d2000000-0000-4000-8000-000000000007';
