select is((select count(*)::int from public.development_safety_instructions),0,'Revoked guardian loses current instruction access');
select throws_ok($$select pg_temp.guidance_save('Revoked guardian cannot edit')$$,'42501',null,'Revoked guardian cannot update instructions');
reset role;
select ok(not exists(select 1 from public.audit_events where entity='development_safety_instructions' and new_value::text like '%Synthetic instruction%'),'Safety text never enters metadata-only audit');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select pg_temp.guidance_save('')$$,'Authorized staff can clear outdated current instructions');
select is((select count(*)::int from public.development_safety_instructions),1,'Clearing replaces the current record without exposing old instruction history');
select is((select instructions from public.development_safety_instructions),'','Cleared instruction no longer exposes the old text');
reset role;
select ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.development_safety_children'::regclass),'Safety projection uses invoker security over the narrowly authorized read function');
select ok(not has_function_privilege('anon','private.development_safety_child_rows()','execute'),'Anonymous role cannot execute the safety projection helper');
select * from finish();
rollback;
